(function () {
'use strict';
function showToast(message) {
var container = document.getElementById('toast-container');
if (!container) {
container = document.createElement('div');
container.id = 'toast-container';
container.className = 'toast-container';
container.setAttribute('aria-live', 'polite');
document.body.appendChild(container);
}
var item = document.createElement('div');
item.className = 'toast-msg';
item.innerHTML = '<span>●</span><span>' + message + '</span>';
container.appendChild(item);
setTimeout(function () {
if (item.parentNode) item.parentNode.removeChild(item);
}, 3400);
}
function initShell() {
var sidebar = document.getElementById('dash-sidebar');
var collapseBtn = document.querySelector('[data-action="collapse-sidebar"]');
var mobileBtn = document.querySelector('[data-action="mobile-sidebar"]');
if (sidebar && localStorage.getItem('medicore_sidebar') === 'collapsed') {
sidebar.classList.add('is-collapsed');
}
if (collapseBtn && sidebar) {
collapseBtn.addEventListener('click', function () {
var collapsed = sidebar.classList.toggle('is-collapsed');
localStorage.setItem('medicore_sidebar', collapsed ? 'collapsed' : 'expanded');
});
}
if (mobileBtn && sidebar) {
mobileBtn.addEventListener('click', function () {
sidebar.classList.toggle('mobile-open');
});
}
var roleSelect = document.getElementById('dash-role-switcher');
var roleMap = {
Admin: ['overview', 'patients', 'beds', 'billing', 'staff', 'appointments', 'messages', 'reports', 'settings'],
Doctor: ['overview', 'patients', 'beds', 'staff', 'appointments', 'messages', 'reports'],
Nurse: ['overview', 'patients', 'beds', 'staff', 'appointments', 'messages'],
Billing: ['overview', 'patients', 'billing', 'appointments', 'messages', 'reports']
};
function applyRole(role) {
var allowed = roleMap[role] || roleMap.Admin;
document.querySelectorAll('.sidebar-link[data-nav-module]').forEach(function (link) {
var mod = link.getAttribute('data-nav-module');
link.style.display = allowed.indexOf(mod) !== -1 ? '' : 'none';
});
var badgeEl = document.getElementById('active-role-badge');
if (badgeEl) badgeEl.textContent = role + ' View';
}
if (roleSelect) {
var savedRole = localStorage.getItem('medicore_role') || 'Admin';
roleSelect.value = savedRole;
applyRole(savedRole);
roleSelect.addEventListener('change', function () {
var nextRole = roleSelect.value;
localStorage.setItem('medicore_role', nextRole);
applyRole(nextRole);
showToast('Switched active RBAC workspace to ' + nextRole + ' Role.');
});
}
var globalSearch = document.getElementById('dash-global-search');
if (globalSearch) {
globalSearch.addEventListener('input', function () {
var q = globalSearch.value.toLowerCase().trim();
document.querySelectorAll('.data-table tbody tr, .bed-tile').forEach(function (el) {
var txt = el.textContent.toLowerCase();
el.style.display = txt.indexOf(q) !== -1 ? '' : 'none';
});
});
}
}
function initModals() {
document.querySelectorAll('[data-open-modal]').forEach(function (btn) {
btn.addEventListener('click', function () {
var id = btn.getAttribute('data-open-modal');
var modal = document.getElementById(id);
if (modal) modal.classList.add('is-open');
});
});
document.querySelectorAll('[data-close-modal]').forEach(function (btn) {
btn.addEventListener('click', function () {
var modal = btn.closest('.modal-backdrop');
if (modal) modal.classList.remove('is-open');
});
});
document.addEventListener('keydown', function (e) {
if (e.key === 'Escape') {
document.querySelectorAll('.modal-backdrop.is-open').forEach(function (m) {
m.classList.remove('is-open');
});
var drawer = document.getElementById('patient-detail-drawer');
if (drawer) drawer.classList.remove('is-open');
}
});
}
function initOverviewCharts() {
if (!window.MediCoreCharts) return;
var admEl = document.getElementById('chart-admissions-trend');
if (admEl) {
window.MediCoreCharts.renderAdmissionsChart(admEl, {
labels: ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'],
ipd: [32, 38, 41, 35, 49, 44, 46],
opd: [145, 162, 178, 154, 190, 168, 182],
discharges: [28, 34, 39, 31, 45, 42, 38]
});
}
var deptEl = document.getElementById('chart-department-load');
if (deptEl) {
window.MediCoreCharts.renderDepartmentLoad(deptEl, [
{ department: 'Cardiology & Cath Lab', patients: 68, capacity: 75 },
{ department: 'Critical Care (ICU/NICU)', patients: 44, capacity: 48 },
{ department: 'Orthopedics & Trauma', patients: 54, capacity: 65 },
{ department: 'Obstetrics & Maternity', patients: 39, capacity: 45 },
{ department: 'Neurology & Stroke Unit', patients: 31, capacity: 40 },
{ department: 'Pediatrics', patients: 29, capacity: 40 }
]);
}
var revEl = document.getElementById('chart-revenue-collections');
if (revEl) {
window.MediCoreCharts.renderRevenueChart(revEl, {
months: ['Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov'],
billedLakhs: [412, 438, 465, 451, 489, 524],
collectedLakhs: [389, 415, 448, 439, 472, 508]
});
}
var donutEl = document.getElementById('chart-bed-donut');
if (donutEl) {
window.MediCoreCharts.renderBedDonut(donutEl, {
occupied: 216,
available: 21,
cleaning: 6,
reserved: 5,
maintenance: 2
});
}
document.querySelectorAll('[data-dismiss-alert]').forEach(function (btn) {
btn.addEventListener('click', function () {
var row = btn.closest('.alert-item');
if (row) row.remove();
showToast('Clinical telemetry alert acknowledged and logged to audit trail.');
});
});
}
function initPatientsModule() {
var table = document.getElementById('patients-table');
if (!table) return;
var searchInp = document.getElementById('patient-search');
var deptFilter = document.getElementById('patient-dept-filter');
var statusChips = document.querySelectorAll('[data-patient-status]');
var activeStatus = 'all';
function filterPatients() {
var q = searchInp ? searchInp.value.toLowerCase().trim() : '';
var dept = deptFilter ? deptFilter.value : 'all';
table.querySelectorAll('tbody tr').forEach(function (row) {
var txt = row.textContent.toLowerCase();
var rowDept = row.getAttribute('data-dept') || '';
var rowStatus = row.getAttribute('data-status') || '';
var matchQ = !q || txt.indexOf(q) !== -1;
var matchD = dept === 'all' || rowDept === dept;
var matchS = activeStatus === 'all' || rowStatus === activeStatus;
row.style.display = (matchQ && matchD && matchS) ? '' : 'none';
});
}
if (searchInp) searchInp.addEventListener('input', filterPatients);
if (deptFilter) deptFilter.addEventListener('change', filterPatients);
statusChips.forEach(function (chip) {
chip.addEventListener('click', function () {
statusChips.forEach(function (c) { c.classList.remove('active'); });
chip.classList.add('active');
activeStatus = chip.getAttribute('data-patient-status');
filterPatients();
});
});
var drawer = document.getElementById('patient-detail-drawer');
var closeDrawerBtn = document.getElementById('close-patient-drawer');
if (closeDrawerBtn && drawer) {
closeDrawerBtn.addEventListener('click', function () {
drawer.classList.remove('is-open');
});
}
function bindDrawerTriggers() {
table.querySelectorAll('[data-open-patient]').forEach(function (btn) {
if (btn.dataset.bound === 'true') return;
btn.dataset.bound = 'true';
btn.addEventListener('click', function () {
var tr = btn.closest('tr');
if (!tr || !drawer) return;
document.getElementById('drawer-pt-name').textContent = tr.getAttribute('data-name') || 'Patient';
document.getElementById('drawer-pt-uhid').textContent = tr.getAttribute('data-uhid') || '';
document.getElementById('drawer-pt-dept').textContent = tr.getAttribute('data-dept') || '';
document.getElementById('drawer-pt-doc').textContent = tr.getAttribute('data-doctor') || '';
document.getElementById('drawer-pt-diag').textContent = tr.getAttribute('data-diagnosis') || '';
document.getElementById('drawer-pt-bp').textContent = tr.getAttribute('data-bp') || '122/78 mmHg';
document.getElementById('drawer-pt-hr').textContent = tr.getAttribute('data-hr') || '76 bpm';
document.getElementById('drawer-pt-spo2').textContent = tr.getAttribute('data-spo2') || '98%';
document.getElementById('drawer-pt-rx').textContent = tr.getAttribute('data-rx') || 'Standard IPD Protocol';
document.getElementById('drawer-pt-lab').textContent = tr.getAttribute('data-lab') || 'CBC & Renal Panel Verified';
document.getElementById('drawer-pt-bill').textContent = tr.getAttribute('data-bill') || 'INV-2026-8841 · Cashless TPA Active';
drawer.classList.add('is-open');
});
});
}
bindDrawerTriggers();
var addForm = document.getElementById('add-patient-form');
if (addForm) {
addForm.addEventListener('submit', function (e) {
e.preventDefault();
var name = document.getElementById('new-pt-name').value.trim();
var age = document.getElementById('new-pt-age').value.trim();
var dept = document.getElementById('new-pt-dept').value;
var doc = document.getElementById('new-pt-doc').value.trim();
var ward = document.getElementById('new-pt-ward').value.trim();
if (!name || !age || !doc || !ward) {
showToast('Please complete all required patient registration fields.');
return;
}
var uhid = 'UHID-2026-' + Math.floor(9050 + Math.random() * 900);
var tbody = table.querySelector('tbody');
var tr = document.createElement('tr');
tr.setAttribute('data-dept', dept);
tr.setAttribute('data-status', 'Admitted');
tr.setAttribute('data-name', name);
tr.setAttribute('data-uhid', uhid);
tr.setAttribute('data-doctor', doc);
tr.setAttribute('data-diagnosis', 'New IPD Admission — Initial Clinical Assessment');
tr.innerHTML =
'<td data-label="Patient"><div class="avatar-cell"><span class="monogram-circle">' + name.slice(0, 2).toUpperCase() + '</span><div><strong>' + name + '</strong><div class="mono" style="font-size:0.75rem;color:var(--text-muted);">' + uhid + '</div></div></div></td>' +
'<td data-label="Age">' + age + ' yrs</td>' +
'<td data-label="Department">' + dept + '</td>' +
'<td data-label="Doctor">' + doc + '</td>' +
'<td data-label="Ward / Bed" class="mono">' + ward + '</td>' +
'<td data-label="Status"><span class="badge badge-teal">Admitted</span></td>' +
'<td data-label="Last Visit" class="mono">2026-11-13</td>' +
'<td data-label="Action"><button type="button" class="btn btn-ghost btn-sm" data-open-patient>View Chart</button></td>';
tbody.insertBefore(tr, tbody.firstChild);
bindDrawerTriggers();
addForm.reset();
var modal = addForm.closest('.modal-backdrop');
if (modal) modal.classList.remove('is-open');
showToast('Patient ' + name + ' (' + uhid + ') admitted and added to EMR.');
});
}
}
function initBedBoard() {
var board = document.getElementById('bed-board-grid');
if (!board) return;
var activeWard = 'all';
var activeStatus = 'all';
var activeTile = null;
function filterBeds() {
board.querySelectorAll('.bed-tile').forEach(function (tile) {
var w = tile.getAttribute('data-ward');
var s = tile.getAttribute('data-status');
var matchW = activeWard === 'all' || w === activeWard;
var matchS = activeStatus === 'all' || s === activeStatus;
tile.style.display = (matchW && matchS) ? '' : 'none';
});
}
document.querySelectorAll('[data-ward-filter]').forEach(function (btn) {
btn.addEventListener('click', function () {
document.querySelectorAll('[data-ward-filter]').forEach(function (b) { b.classList.remove('active'); });
btn.classList.add('active');
activeWard = btn.getAttribute('data-ward-filter');
filterBeds();
});
});
document.querySelectorAll('[data-bedstatus-filter]').forEach(function (btn) {
btn.addEventListener('click', function () {
document.querySelectorAll('[data-bedstatus-filter]').forEach(function (b) { b.classList.remove('active'); });
btn.classList.add('active');
activeStatus = btn.getAttribute('data-bedstatus-filter');
filterBeds();
});
});
var bedModal = document.getElementById('bed-action-modal');
var bedForm = document.getElementById('bed-action-form');
board.querySelectorAll('.bed-tile').forEach(function (tile) {
tile.addEventListener('click', function () {
activeTile = tile;
if (!bedModal) return;
document.getElementById('modal-bed-id').textContent = tile.getAttribute('data-bed-id');
document.getElementById('modal-bed-status').value = tile.getAttribute('data-status');
document.getElementById('modal-bed-patient').value = tile.getAttribute('data-patient') || '';
bedModal.classList.add('is-open');
});
});
if (bedForm) {
bedForm.addEventListener('submit', function (e) {
e.preventDefault();
if (!activeTile) return;
var newStatus = document.getElementById('modal-bed-status').value;
var newPt = document.getElementById('modal-bed-patient').value.trim();
activeTile.className = 'mc-card card-anim-ring bed-tile status-' + newStatus;
activeTile.setAttribute('data-status', newStatus);
activeTile.setAttribute('data-patient', newPt);
var badge = activeTile.querySelector('.bed-status-badge');
if (badge) {
badge.textContent = newStatus;
badge.className = 'badge bed-status-badge ' +
(newStatus === 'Occupied' ? 'badge-signal' :
newStatus === 'Available' ? 'badge-emerald' :
newStatus === 'Cleaning' ? 'badge-amber' : 'badge-teal');
}
var ptLabel = activeTile.querySelector('.bed-patient-name');
if (ptLabel) {
ptLabel.textContent = newPt || (newStatus === 'Available' ? 'Sterile & Ready for Admission' : newStatus);
}
bedModal.classList.remove('is-open');
showToast('Bed ' + activeTile.getAttribute('data-bed-id') + ' updated to ' + newStatus + '.');
});
}
}
function initBillingModule() {
var invTable = document.getElementById('billing-table');
if (!invTable) return;
document.querySelectorAll('[data-invoice-filter]').forEach(function (chip) {
chip.addEventListener('click', function () {
document.querySelectorAll('[data-invoice-filter]').forEach(function (c) { c.classList.remove('active'); });
chip.classList.add('active');
var status = chip.getAttribute('data-invoice-filter');
invTable.querySelectorAll('tbody tr').forEach(function (row) {
var rStat = row.getAttribute('data-status');
row.style.display = (status === 'all' || rStat === status) ? '' : 'none';
});
});
});
var createForm = document.getElementById('create-invoice-form');
if (createForm) {
var rateInp = document.getElementById('inv-item-rate');
var qtyInp = document.getElementById('inv-item-qty');
var taxInp = document.getElementById('inv-tax-pct');
var totalPreview = document.getElementById('inv-computed-total');
function updateCalc() {
var r = parseFloat(rateInp ? rateInp.value : 0) || 0;
var q = parseFloat(qtyInp ? qtyInp.value : 1) || 1;
var t = parseFloat(taxInp ? taxInp.value : 0) || 0;
var sum = Math.round(r * q * (1 + t / 100));
if (totalPreview) totalPreview.textContent = '₹' + sum.toLocaleString('en-IN');
return sum;
}
[rateInp, qtyInp, taxInp].forEach(function (el) {
if (el) el.addEventListener('input', updateCalc);
});
createForm.addEventListener('submit', function (e) {
e.preventDefault();
var pt = document.getElementById('inv-patient-name').value.trim();
var payer = document.getElementById('inv-payer').value;
var sum = updateCalc();
if (!pt || sum <= 0) {
showToast('Please enter patient name and valid line item amount.');
return;
}
var invId = 'INV-2026-' + Math.floor(8850 + Math.random() * 140);
var tbody = invTable.querySelector('tbody');
var tr = document.createElement('tr');
tr.setAttribute('data-status', 'Pending');
tr.innerHTML =
'<td data-label="Invoice ID" class="mono"><strong>' + invId + '</strong></td>' +
'<td data-label="Patient">' + pt + '</td>' +
'<td data-label="Payer / TPA">' + payer + '</td>' +
'<td data-label="Total Billed" class="mono">₹' + sum.toLocaleString('en-IN') + '</td>' +
'<td data-label="Claim Stage">Pre-Auth Submitted</td>' +
'<td data-label="Status"><span class="badge badge-amber">Pending</span></td>' +
'<td data-label="Actions"><button type="button" class="btn btn-ghost btn-sm" onclick="window.print()">Print Receipt</button></td>';
tbody.insertBefore(tr, tbody.firstChild);
createForm.reset();
updateCalc();
var modal = createForm.closest('.modal-backdrop');
if (modal) modal.classList.remove('is-open');
showToast('Invoice ' + invId + ' generated and dispatched to billing ledger.');
});
}
}
function initOperationsModules() {
var shiftForm = document.getElementById('assign-shift-form');
if (shiftForm) {
shiftForm.addEventListener('submit', function (e) {
e.preventDefault();
var doc = document.getElementById('shift-staff-name').value;
var day = document.getElementById('shift-day').value;
var type = document.getElementById('shift-type').value;
var modal = shiftForm.closest('.modal-backdrop');
if (modal) modal.classList.remove('is-open');
showToast('Assigned ' + type + ' shift to ' + doc + ' for ' + day + '.');
});
}
document.querySelectorAll('[data-approve-leave]').forEach(function (btn) {
btn.addEventListener('click', function () {
btn.textContent = 'Approved';
btn.disabled = true;
showToast('Leave request approved and cross-cover roster updated.');
});
});
document.querySelectorAll('[data-appt-next]').forEach(function (btn) {
btn.addEventListener('click', function () {
var row = btn.closest('tr, .mc-card');
var badge = row ? row.querySelector('.appt-status-badge') : null;
if (badge) {
badge.textContent = 'In Consultation';
badge.className = 'badge badge-teal appt-status-badge';
}
showToast('Patient checked into OPD consultation room.');
});
});
var apptForm = document.getElementById('book-appointment-form');
if (apptForm) {
apptForm.addEventListener('submit', function (e) {
e.preventDefault();
var pt = document.getElementById('appt-pt-name').value.trim();
var doc = document.getElementById('appt-doc-select').value;
var time = document.getElementById('appt-time-slot').value;
if (!pt) return;
var modal = apptForm.closest('.modal-backdrop');
if (modal) modal.classList.remove('is-open');
apptForm.reset();
showToast('Appointment booked for ' + pt + ' with ' + doc + ' at ' + time + '.');
});
}
var replyForm = document.getElementById('message-reply-form');
if (replyForm) {
replyForm.addEventListener('submit', function (e) {
e.preventDefault();
var textInp = document.getElementById('message-reply-input');
var threadLog = document.getElementById('message-thread-log');
if (!textInp || !textInp.value.trim() || !threadLog) return;
var div = document.createElement('div');
div.className = 'dash-panel';
div.style.marginBottom = '12px';
div.style.borderColor = 'var(--primary)';
div.innerHTML =
'<div style="display:flex;justify-content:space-between;font-size:0.8rem;margin-bottom:6px;">' +
'<strong>You (Clinical Duty Desk)</strong><span class="mono">Just now</span></div>' +
'<p style="margin:0;">' + textInp.value.trim() + '</p>';
threadLog.appendChild(div);
textInp.value = '';
showToast('Clinical reply transmitted with HIPAA audit timestamp.');
});
}
var resetBtn = document.getElementById('reset-demo-data-btn');
if (resetBtn) {
resetBtn.addEventListener('click', function () {
localStorage.removeItem('medicore_role');
localStorage.removeItem('medicore_sidebar');
showToast('Demo workspace state reset to default hospital configuration.');
});
}
}
window.MediCoreDash = { toast: showToast };
document.addEventListener('DOMContentLoaded', function () {
initShell();
initModals();
initOverviewCharts();
initPatientsModule();
initBedBoard();
initBillingModule();
initOperationsModules();
});
})();